  retry_count: Math.max(0, Number(i.retry_count ?? 0)),
  retry_delays: (() => {
  const raw = i.retry_delays;

  if (Array.isArray(raw)) {
    return raw.map(Number).filter(Number.isFinite);
  }

  if (typeof raw === 'string' && raw.trim()) {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        return parsed.map(Number).filter(Number.isFinite);
      }
    } catch (_) {
      // fallback below
    }
  }

  return [15, 30, 60, 120, 300];
})(),
  retry_delay_seconds: 0,
  status: '', route: '', output: '', error: '', error_code: '', http_code: null,
  run_not_found: false, transient_error: false, resumed: false,
  session_verified: !String(i.session_id ?? '').trim(), session_mismatch: false
};
if (!state.model) throw new Error('Hermes Run Manager: model is required.');
if (!state.provider) throw new Error('Hermes Run Manager: provider is required.');
if (!state.input && !state.resume_input && !state.run_id) throw new Error('Hermes Run Manager: input is required.');
