  if (!returnedRun) return { ...prior, run_id: '', session_id: returnedSession || requested, status: 'failed', route: 'start_error', output: '', error: err.text || 'Hermes did not return run_id.', error_code: err.code || 'run_start_failed', session_verified: false, session_mismatch: false };
  return { ...prior, run_id: returnedRun, session_id: returnedSession || requested, status: String(r.status ?? 'started').toLowerCase(), route: 'running', output: String(r.output ?? r.response ?? r.content ?? ''), error: err.text, error_code: err.code, resumed: Boolean(resumed), session_verified: !requested || !returnedSession || returnedSession === requested, session_mismatch: false };
