function baseState() {
  if ($('Evaluate Status').isExecuted) return $('Evaluate Status').last().json;
  if ($('Capture Run Response').isExecuted) return $('Capture Run Response').last().json;
  return $('Normalize Request').last().json;
}

const envelope = $json ?? {};
const r = parse(envelope?.body ?? envelope?.data ?? envelope);
const prior = baseState();
const status = String(r.status ?? '').toLowerCase();
const raw = r.error ?? r.message ?? r.details ?? r.detail ?? '';
const errorText = typeof raw === 'string' ? raw : String(raw?.message ?? raw?.detail ?? r.details ?? '');
const errorCode = String(
  typeof raw === 'object' && raw
    ? (raw.code ?? r.code ?? '')
    : (r.code ?? '')
).toLowerCase();
const lower = errorText.toLowerCase();

const envelopeHttp = Number(
  envelope.statusCode ?? envelope.status_code ?? envelope.httpCode ?? envelope.http_code ?? NaN
);
const bodyHttp = Number(
  r.statusCode ?? r.status_code ?? r.httpCode ?? r.http_code ?? NaN
);
const match = errorText.match(/\b(4\d\d|5\d\d)\b/);
const httpCode = Number.isFinite(envelopeHttp) ? envelopeHttp
  : Number.isFinite(bodyHttp) ? bodyHttp
  : (match ? Number(match[1]) : null);

const runNotFound =
  httpCode === 404 ||
  errorCode === 'run_not_found' ||
  errorCode === 'not_found' ||
  lower.includes('run not found') ||
  lower.includes('run_not_found');

const transientCodes = new Set([408,409,425,429,500,502,503,504,529]);
